'use client';

import { useTranslation, Log } from '@fanfanlo';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControlLabel,
  Stack,
} from '@mui/material';
import { useProjectSettings } from '../context/ProjectSettingsContext';

const fileLog = new Log(false, 'DeleteConfirmDialog');
fileLog.pause = false;

export function DeleteConfirmDialog() {
  const { t } = useTranslation('homepage/components/project/ProjectSettingsContent/components/content');
  const {
    deleteConfirmOpen,
    setDeleteConfirmOpen,
    deleteFromLocal,
    setDeleteFromLocal,
    deleteFromServer,
    setDeleteFromServer,
    saving,
    handleDelete,
    error,
    isUserLoggedIn,
  } = useProjectSettings();

  fileLog.log('[DeleteConfirmDialog] isUserLoggedIn:', isUserLoggedIn);

  return (
    <Dialog
      data-testid="ProjectSettingsContent__deleteDialog__01JG2B008E"
      open={deleteConfirmOpen}
      onClose={() => setDeleteConfirmOpen(false)}
    >
      <DialogTitle>{t('DeleteConfirmDialog.title')}</DialogTitle>
      <DialogContent>
        <Stack spacing={2} sx={{ marginTop: 1 }}>
          {isUserLoggedIn ? (
            <>
              {error ? (
                <Alert
                  data-testid="ProjectSettingsContent__deleteErrorAlert__01JG2B008F"
                  data-test-comment="删除错误提示"
                  severity="error"
                >
                  {error}
                </Alert>
              ) : null}

              <Box>
                <FormControlLabel
                  control={
                    <Checkbox
                      data-testid="ProjectSettingsContent__deleteServerCheckbox__01JG2B008A"
                      data-test-comment="从服务器删除复选框"
                      checked={deleteFromServer}
                      onChange={(e) => setDeleteFromServer(e.target.checked)}
                      disabled={deleteFromLocal}
                    />
                  }
                  label={t('DeleteConfirmDialog.deleteFromServer')}
                />
                <Box sx={{ marginLeft: 4, marginTop: 1, fontSize: '0.875rem', color: 'text.secondary' }}>
                  {t('DeleteConfirmDialog.deleteServerInfo')}
                </Box>
              </Box>

              <Box>
                <FormControlLabel
                  control={
                    <Checkbox
                      data-testid="ProjectSettingsContent__deleteLocalCheckbox__01JG2B008B"
                      data-test-comment="从本地删除复选框"
                      checked={deleteFromLocal}
                      onChange={(e) => setDeleteFromLocal(e.target.checked)}
                    />
                  }
                  label={t('DeleteConfirmDialog.deleteFromLocal')}
                />
                <Box sx={{ marginLeft: 4, marginTop: 1, fontSize: '0.875rem', color: 'text.secondary' }}>
                  {t('DeleteConfirmDialog.deleteLocalInfo')}
                </Box>
              </Box>
            </>
          ) : (
            <>
              {error ? (
                <Alert
                  data-testid="ProjectSettingsContent__deleteErrorAlertNotLoggedIn__01JG2B008G"
                  data-test-comment="未登录时删除错误提示"
                  severity="error"
                >
                  {error}
                </Alert>
              ) : null}

              <Alert
                data-testid="ProjectSettingsContent__deleteConfirmAlertNotLoggedIn__01JG2B008H"
                data-test-comment="未登录时删除确认提示"
                severity="warning"
              >
                {t('DeleteConfirmDialog.warningNotLoggedIn')}
              </Alert>
            </>
          )}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button
          data-testid="ProjectSettingsContent__deleteCancelButton__01JG2B008C"
          data-test-comment="删除确认对话框取消按钮"
          onClick={() => setDeleteConfirmOpen(false)}
        >
          {t('DeleteConfirmDialog.cancel')}
        </Button>
        <Button
          data-testid="ProjectSettingsContent__deleteConfirmButton__01JG2B008D"
          data-test-comment="删除确认按钮"
          onClick={handleDelete}
          color="error"
          variant="contained"
          disabled={isUserLoggedIn ? ((!deleteFromLocal && !deleteFromServer) || saving) : saving}
        >
          {saving ? <CircularProgress size={24} /> : t('DeleteConfirmDialog.delete')}
        </Button>
      </DialogActions>
    </Dialog>
  );
}
