'use client';

import { useTranslation } from '@fanfanlo';
import { Alert, Box, Checkbox, FormControlLabel } from '@mui/material';
import { useProjectSettings } from '../context/ProjectSettingsContext';

export function ShareSection() {
  const { t } = useTranslation('homepage/components/project/ProjectSettingsContent/components/content');
  const { isPublic, setIsPublic } = useProjectSettings();

  return (
    <Box>
      <FormControlLabel
        control={
          <Checkbox
            data-testid="ProjectSettingsContent__shareCheckbox__01JG2B0086"
            data-test-comment="与他人共享复选框"
            checked={isPublic}
            onChange={(e) => setIsPublic(e.target.checked)}
          />
        }
        label={t('ShareSection.label')}
      />
      <Alert severity="info" sx={{ marginTop: 1 }}>
        {t('ShareSection.info')}
      </Alert>
    </Box>
  );
}
