'use client';

import { useTranslation } from '@fanfanlo';
import { Alert, Box, Checkbox, FormControlLabel } from '@mui/material';
import { useProjectSettings } from '../context/ProjectSettingsContext';

export function SyncToServerSection() {
  const { t } = useTranslation('homepage/components/project/ProjectSettingsContent/components/content');
  const { syncToServer, setSyncToServer } = useProjectSettings();

  return (
    <Box>
      <FormControlLabel
        control={
          <Checkbox
            data-testid="ProjectSettingsContent__syncToServerCheckbox__01JG2B0085"
            data-test-comment="同步到服务器复选框"
            checked={syncToServer}
            onChange={(e) => setSyncToServer(e.target.checked)}
          />
        }
        label={t('SyncToServerSection.label')}
      />
      <Alert severity="warning" sx={{ marginTop: 1 }}>
        {t('SyncToServerSection.warning')}
      </Alert>
    </Box>
  );
}
